css:
.trsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1f2a37;
    background: linear-gradient(180deg, #f4f6fa 0%, #eef1f7 100%);
    border-radius: 16px;
    border: 1px solid #d8dee9;
}

.trsim-container * {
    box-sizing: border-box;
}

.trsim-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #0c2342 0%, #143a5c 60%, #0f5132 100%);
    color: #eef4fb;
    border-radius: 14px;
    margin-bottom: 20px;
    box-shadow: 0 12px 30px rgba(12, 35, 66, 0.30);
}

.trsim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.trsim-header-tag {
    display: inline-block;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 1.1px;
    font-weight: 700;
    color: #d4af37;
    background: rgba(212, 175, 55, 0.12);
    border: 1px solid rgba(212, 175, 55, 0.40);
    padding: 5px 14px;
    border-radius: 4px;
}

.trsim-subtitle {
    margin: 0 auto;
    max-width: 820px;
    font-size: 1rem;
    line-height: 1.55;
    color: #cdd9e8;
}

.trsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #51607a;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.trsim-period-counter #currentDay,
.trsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #0f5132;
}

.trsim-round-name {
    background: rgba(15, 81, 50, 0.10);
    color: #0f5132;
    padding: 3px 12px;
    border-radius: 4px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.trsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #8a5a00;
    background: rgba(212, 175, 55, 0.18);
    border: 1px solid rgba(212, 175, 55, 0.50);
    padding: 4px 12px;
    border-radius: 4px;
}

.trsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.trsim-status-card {
    background: #ffffff;
    border-radius: 10px;
    padding: 16px 16px 14px;
    border: 1px solid #dde3ec;
    box-shadow: 0 4px 14px rgba(12, 35, 66, 0.07);
    border-top: 4px solid #143a5c;
}

.trsim-card-progress { border-top-color: #0f5132; }
.trsim-card-compliance { border-top-color: #143a5c; }
.trsim-card-quality { border-top-color: #7048a8; }
.trsim-card-roi { border-top-color: #b8860b; }

.trsim-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    font-weight: 700;
    color: #6b7787;
}

.trsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #0c2342;
    font-variant-numeric: tabular-nums;
}

.trsim-card-progress .trsim-value { color: #0f5132; }
.trsim-card-compliance .trsim-value { color: #143a5c; }
.trsim-card-quality .trsim-value { color: #7048a8; }
.trsim-card-roi .trsim-value { color: #b8860b; }

.trsim-sublabel {
    font-size: 0.75rem;
    color: #7e8a9a;
    line-height: 1.35;
}

.trsim-roi-negative .trsim-value { color: #c0392b; }
.trsim-roi-positive .trsim-value { color: #0f5132; }

.trsim-compliance-breach { border-top-color: #c0392b; }
.trsim-compliance-breach .trsim-value { color: #c0392b; }
.trsim-compliance-strong { border-top-color: #0f5132; }
.trsim-compliance-strong .trsim-value { color: #0f5132; }

.trsim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #0c2342;
    color: #dbe5f1;
    padding: 11px 18px;
    border-radius: 8px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.trsim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #d4af37;
}

.trsim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #0f5132;
    border-radius: 10px;
    padding: 16px 18px;
    margin-bottom: 18px;
    border: 1px solid #dde3ec;
    box-shadow: 0 4px 14px rgba(12, 35, 66, 0.07);
}

.trsim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.trsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #0c2342;
    margin-bottom: 6px;
}

.trsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #3a4759;
}

.trsim-briefing-text strong { color: #0f5132; }
.trsim-briefing-text em { color: #8a5a00; font-style: italic; }

.trsim-controls {
    background: #ffffff;
    border-radius: 12px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #dde3ec;
    box-shadow: 0 4px 14px rgba(12, 35, 66, 0.07);
}

.trsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #0c2342;
    border-bottom: 2px solid #e6eaf1;
    padding-bottom: 8px;
}

.trsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #2a3645;
    margin: 14px 0 6px;
}

.trsim-container select,
.trsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #c3cdda;
    border-radius: 7px;
    font-size: 0.92rem;
    background-color: #ffffff;
    color: #1f2a37;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.trsim-container select:focus,
.trsim-container input[type="number"]:focus {
    outline: none;
    border-color: #0f5132;
    box-shadow: 0 0 0 3px rgba(15, 81, 50, 0.15);
}

.trsim-container select option {
    background-color: #ffffff;
    color: #1f2a37;
}

.trsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #0f5132;
}

.trsim-range-readout,
.trsim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #51607a;
    margin-top: 4px;
}

.trsim-range-readout span:last-child,
.trsim-alloc-readout span:nth-child(2) {
    color: #0f5132;
    font-weight: 800;
}

.trsim-hint {
    font-size: 0.8rem;
    color: #7e8a9a;
    margin-top: 4px;
    line-height: 1.4;
}

.trsim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.trsim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f6f8fb;
    border: 1px solid #dde3ec;
    border-radius: 7px;
    padding: 8px 12px;
}

.trsim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #2a3645;
}

.trsim-alloc-row input[type="number"] {
    width: 90px;
    flex: 0 0 90px;
}

.trsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.trsim-container .btn-primary {
    background: linear-gradient(135deg, #0f5132 0%, #157347 100%);
    border: none;
    color: #ffffff;
    padding: 11px 28px;
    border-radius: 7px;
    box-shadow: 0 8px 18px rgba(15, 81, 50, 0.30);
}

.trsim-container .btn-primary:hover {
    filter: brightness(1.07);
}

.trsim-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid #c3cdda;
    color: #51607a;
    background: transparent;
}

.trsim-coach {
    background: linear-gradient(160deg, #0c2342 0%, #102b1e 100%);
    color: #d8e4f0;
    border: 1px solid #143a5c;
    border-radius: 12px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(12, 35, 66, 0.25);
}

.trsim-coach-header {
    font-size: 0.76rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #d4af37;
    margin-bottom: 8px;
}

.trsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.trsim-coach-body strong { color: #5fd99a; }
.trsim-coach-body em { color: #e6c258; font-style: italic; }

.trsim-history,
.trsim-chart {
    background: #ffffff;
    border-radius: 12px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #dde3ec;
    box-shadow: 0 4px 14px rgba(12, 35, 66, 0.07);
}

.trsim-history h3,
.trsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #0c2342;
}

.trsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #2a3645;
}

.trsim-container table#usfHistoryTable th {
    background: #0c2342;
    color: #d4af37;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.7rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #143a5c;
}

.trsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #e6eaf1;
    color: #3a4759;
}

.trsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f6f8fb;
}

.trsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .trsim-container {
        padding: 14px;
    }
    .trsim-header h1 {
        font-size: 1.7rem;
    }
    .trsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .trsim-value {
        font-size: 2rem;
    }
    .trsim-clock {
        margin-left: 0;
    }
    .trsim-period-counter {
        font-size: 0.88rem;
    }
    .trsim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .trsim-alloc-row {
        flex-wrap: wrap;
    }
    .trsim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .trsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

/* ============================================================
   v1.1.0 — Completion debrief (append-only, scoped .tr-cm)
   Palette: green #0f5132 · navy #0c2342 · gold #d4af37 · red #c0392b
   ============================================================ */
.tr-cm { font-family: inherit; color: #1f2a37; text-align: left; }
.tr-cm-head { display: flex; align-items: center; gap: 20px; flex-wrap: wrap;
    border-bottom: 3px solid #d4af37; padding-bottom: 14px; margin-bottom: 16px; }
.tr-cm-scorebox { display: flex; flex-direction: column; align-items: center;
    background: #0f5132; color: #fff; border-radius: 12px; padding: 12px 20px; min-width: 130px; }
.tr-cm-score { font-size: 2.6rem; line-height: 1; font-weight: 800; }
.tr-cm-score-max { font-size: 1rem; font-weight: 600; opacity: 0.78; margin-left: 2px; }
.tr-cm-score-label { font-size: 0.72rem; text-transform: uppercase; letter-spacing: 0.06em; opacity: 0.85; margin-top: 4px; }
.tr-cm-tier { font-size: 1.5rem; font-weight: 700; color: #0c2342; flex: 1 1 auto; }
.tr-cm-chips { display: flex; gap: 12px; flex-wrap: wrap; margin-bottom: 16px; }
.tr-cm-chip { flex: 1 1 200px; display: flex; align-items: center; gap: 10px;
    background: #f6f8fb; border: 1px solid #dde3ec; border-left: 5px solid #51607a;
    border-radius: 8px; padding: 10px 14px; }
.tr-cm-chip.is-met { border-left-color: #0f5132; }
.tr-cm-chip.is-missed { border-left-color: #c0392b; }
.tr-cm-chip-l { font-weight: 600; color: #2a3645; }
.tr-cm-badge { margin-left: auto; font-size: 0.72rem; font-weight: 700; text-transform: uppercase;
    letter-spacing: 0.04em; padding: 3px 9px; border-radius: 999px; color: #fff; }
.tr-cm-badge.is-met { background: #0f5132; }
.tr-cm-badge.is-missed { background: #c0392b; }
.tr-cm-kpis { display: flex; gap: 10px; flex-wrap: wrap; margin-bottom: 18px; }
.tr-cm-kpi { flex: 1 1 120px; text-align: center; background: #fff; border: 1px solid #dde3ec;
    border-top: 3px solid #143a5c; border-radius: 8px; padding: 10px 8px; }
.tr-cm-kpi-v { font-size: 1.3rem; font-weight: 800; color: #0c2342; font-variant-numeric: tabular-nums; }
.tr-cm-kpi-l { font-size: 0.72rem; text-transform: uppercase; letter-spacing: 0.04em; color: #51607a; margin-top: 3px; }
.tr-cm-insights-title { font-weight: 700; color: #0c2342; margin-bottom: 6px; }
.tr-cm-insights ul { margin: 0; padding-left: 20px; }
.tr-cm-insights li { margin-bottom: 7px; line-height: 1.5; }

js:
(function() {
    'use strict';

    class TransformAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Transform Under Rules`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Assicura Verde S.p.A.).
            this.BUDGET = 90;            // EUR 90M, three-year transformation budget
            this.GWP = 3100;             // EUR 3.1B gross written premium (EUR M)
            this.AGENT_PREMIUM = 2400;   // EUR 2.4B via tied agents (EUR M)
            this.REMEDIATION = 15;       // EUR 12–18M AI-pricing remediation risk (midpoint, EUR M)
            this.LUMO_AT_RISK = 70;      // ~EUR 70M motor premium at risk to Lumo over 3 yrs (EUR M)
            this.MODEL_GAIN = 4;         // 4-point combined-ratio gain the model projects

            // Concept truths used for "sharp diagnosis" signposting.
            this.TRUE_THREAT = `all`;
            this.TRUE_BOX = `parameter`;
            this.TRUE_PATH = `balanced`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    progress: 10,            // transformation progress vs Lumo, sequenced (0–100)
                    compliance: 60,          // EU AI Act / IVASS / Solvency II standing (0–100)
                    quality: 25,             // intuition+analytics+agent-goodwill decision quality (0–100)
                    roi: 0,                  // EUR M 3-yr net value created vs status quo
                    budgetUsed: 0,           // EUR M of transformation capital committed
                    ivassFinding: false,     // skipped a gate -> supervisory finding
                    agentRevolt: false,      // ignored the agents -> channel slowdown
                    strandedCapital: false,  // ungated up-front commitment that slipped
                    progressHistory: [10],
                    complianceHistory: [60],
                    qualityHistory: [25],
                    roiHistory: [0],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults are a deliberately fast-and-wrong mix —
                // a blind click-through must NOT auto-win.
                state.decisions = {
                    threat: `speed`,
                    box: `obstacle`,
                    thesis: 40,
                    path: `direct`,
                    platformSpend: 25,
                    agentSpend: 20,
                    aiSpend: 25,
                    directSpend: 20,
                    gating: `upfront`,
                    launch: `modeled`,
                    oversight: `none`,
                    segment: 60,
                    sequence: `aifirst`,
                    gate: `postlaunch`,
                    agentPlan: `none`,
                    pitch: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const th = document.getElementById(`threatInput`);
                const bx = document.getElementById(`boxInput`);
                const ts = document.getElementById(`thesisInput`);
                if (th) decisions.threat = th.value;
                if (bx) decisions.box = bx.value;
                if (ts) decisions.thesis = parseInt(ts.value, 10);
                if (!Number.isFinite(decisions.thesis) || decisions.thesis < 0 || decisions.thesis > 100) {
                    warn(`warn_thesis_range`); return false;
                }
            } else if (round === 2) {
                const pa = document.getElementById(`pathInput`);
                const pl = document.getElementById(`platformSpendInput`);
                const ag = document.getElementById(`agentSpendInput`);
                const ai = document.getElementById(`aiSpendInput`);
                const di = document.getElementById(`directSpendInput`);
                const ga = document.getElementById(`gatingInput`);
                if (pa) decisions.path = pa.value;
                if (pl) decisions.platformSpend = parseFloat(pl.value);
                if (ag) decisions.agentSpend = parseFloat(ag.value);
                if (ai) decisions.aiSpend = parseFloat(ai.value);
                if (di) decisions.directSpend = parseFloat(di.value);
                if (ga) decisions.gating = ga.value;
                const parts = [decisions.platformSpend, decisions.agentSpend, decisions.aiSpend, decisions.directSpend];
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_alloc_negative`); return false;
                }
                const total = Math.round(decisions.platformSpend + decisions.agentSpend + decisions.aiSpend + decisions.directSpend);
                if (Math.abs(total - this.BUDGET) > 0.001) {
                    warn(`warn_alloc_total`); return false;
                }
            } else if (round === 3) {
                const la = document.getElementById(`launchInput`);
                const ov = document.getElementById(`oversightInput`);
                const sg = document.getElementById(`segmentInput`);
                if (la) decisions.launch = la.value;
                if (ov) decisions.oversight = ov.value;
                if (sg) decisions.segment = parseInt(sg.value, 10);
                if (!Number.isFinite(decisions.segment) || decisions.segment < 0 || decisions.segment > 100) {
                    warn(`warn_segment_range`); return false;
                }
            } else if (round === 4) {
                const sq = document.getElementById(`sequenceInput`);
                const gt = document.getElementById(`gateInput`);
                const ap = document.getElementById(`agentPlanInput`);
                const pi = document.getElementById(`pitchInput`);
                if (sq) decisions.sequence = sq.value;
                if (gt) decisions.gate = gt.value;
                if (ap) decisions.agentPlan = ap.value;
                if (pi) decisions.pitch = parseInt(pi.value, 10);
                if (!Number.isFinite(decisions.pitch) || decisions.pitch < 0 || decisions.pitch > 100) {
                    warn(`warn_pitch_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let progressDelta = 0, complianceDelta = 0, qualityDelta = 0, roiDelta = 0, spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose the threat as ONE interlocking system; treat regulation as a design parameter.
                switch (d.threat) {
                    case `all`: progressDelta += 8; qualityDelta += 8; coachKey = `coach_r1_all`; break;
                    case `speed`: progressDelta += 3; qualityDelta -= 4; coachKey = `coach_r1_speed`; break;
                    case `channel`: progressDelta += 2; qualityDelta -= 2; coachKey = `coach_r1_channel`; break;
                    case `data`: progressDelta += 3; qualityDelta -= 2; coachKey = `coach_r1_data`; break;
                }

                switch (d.box) {
                    case `parameter`: complianceDelta += 10; qualityDelta += 8; if (d.threat === `all`) coachKey = `coach_r1_sharp`; break;
                    case `obstacle`: complianceDelta -= 6; qualityDelta -= 4; coachKey = `coach_r1_obstacle`; break;
                    case `ignore`: complianceDelta -= 12; qualityDelta -= 6; coachKey = `coach_r1_ignore`; break;
                }

                if (d.thesis >= 60) { qualityDelta += 6; progressDelta += 3; }
                else if (d.thesis <= 25) { qualityDelta -= 5; coachKey = `coach_r1_lowthesis`; }

                summaryKey = (d.threat === `all` && d.box === `parameter`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Choose the path, allocate EUR 90M, set gating (Common Errors 4 & 5).
                const plat = d.platformSpend, agent = d.agentSpend, ai = d.aiSpend, direct = d.directSpend;

                // Path trade-offs: speed vs defensibility vs regulatory/agent risk.
                switch (d.path) {
                    case `platform`: progressDelta += 6; complianceDelta += 4; qualityDelta += 4; coachKey = `coach_r2_platform`; break;
                    case `channel`: progressDelta += 3; complianceDelta += 3; qualityDelta += 5; coachKey = `coach_r2_channel`; break;
                    case `direct`: progressDelta += 10; complianceDelta -= 8; qualityDelta -= 6; ds.agentRevolt = (agent < 15); coachKey = `coach_r2_direct`; break;
                    case `balanced`: progressDelta += 9; complianceDelta += 5; qualityDelta += 8; coachKey = `coach_r2_balanced`; break;
                }

                // The data platform is the dependency everything sits on — starve it and AI/direct strand.
                if (plat < 15) { progressDelta -= 5; qualityDelta -= 5; coachKey = `coach_r2_noplatform`; }
                else if (plat >= 25) { progressDelta += 3; }

                // Channel-conflict management: under-fund the agents and the 78%-premium network revolts.
                if (agent < 10) { qualityDelta -= 8; progressDelta -= 5; roiDelta -= 18; ds.agentRevolt = true; if (coachKey === `coach_default` || d.path !== `direct`) coachKey = `coach_r2_noagent`; }
                else if (agent >= 20) { qualityDelta += 4; }

                // Gating logic — front-loading everything strands capital when a dependency slips.
                switch (d.gating) {
                    case `milestone`: progressDelta += 6; complianceDelta += 4; qualityDelta += 6; roiDelta += 8; break;
                    case `calendar`: qualityDelta += 1; break;
                    case `upfront`: qualityDelta -= 6; roiDelta -= 12; ds.strandedCapital = true; coachKey = `coach_r2_upfront`; break;
                }

                // ROI signal from the allocation balance (agents protect the 2.4B book; platform compounds).
                roiDelta += (agent * 0.4) + (plat * 0.3) - (direct * 0.2);

                summaryKey = (d.path === `balanced` || d.path === `platform`) && d.gating === `milestone` && agent >= 15 ? `sum_r2_good` :
                             (d.path === `direct` && agent < 15 ? `sum_r2_direct` :
                             (d.gating === `upfront` ? `sum_r2_ungated` : `sum_r2_weak`));
            } else if (round === 3) {
                // Intuition vs analytics: rule on the pay-how-you-drive launch (Common Errors 1, 2, 3).
                const seg = d.segment / 100;

                // Launch posture.
                switch (d.launch) {
                    case `guardrails`: progressDelta += 8; qualityDelta += 10; roiDelta += 14; coachKey = `coach_r3_guardrails`; break;
                    case `modeled`: progressDelta += 10; qualityDelta -= 10; complianceDelta -= 6; coachKey = `coach_r3_modeled`; break;
                    case `reject`: progressDelta -= 8; qualityDelta -= 4; complianceDelta += 2; roiDelta -= 10; coachKey = `coach_r3_reject`; break;
                    case `delay`: progressDelta -= 2; qualityDelta += 4; complianceDelta += 8; roiDelta -= 4; coachKey = `coach_r3_delay`; break;
                }

                // Human-oversight & bias-testing protocol (EU AI Act high-risk obligation).
                switch (d.oversight) {
                    case `control`: complianceDelta += 12; qualityDelta += 8; break;
                    case `paper`: complianceDelta += 2; qualityDelta -= 2; break;
                    case `none`: complianceDelta -= 10; qualityDelta -= 4; if (coachKey === `coach_default`) coachKey = `coach_r3_nooversight`; break;
                }

                // The young-driver tail risk: a wide exposure with an over-fitted, unguarded model bites.
                const unguarded = (d.oversight !== `control`);
                if (d.launch === `modeled` && unguarded) {
                    // Mis-priced young-driver risk scales with the book exposed.
                    roiDelta -= seg * 24;
                    complianceDelta -= seg * 8;
                    if (seg >= 0.6) { ds.ivassFinding = true; coachKey = `coach_r3_blindmodel`; }
                } else if (d.launch === `guardrails`) {
                    // Guardrailed pilot earns more the wider the controlled exposure — but caps the downside.
                    roiDelta += seg * 8;
                }

                // Skipping the gate entirely (modeled launch, no oversight, wide book) = IVASS finding.
                if (d.launch === `modeled` && d.oversight === `none` && seg >= 0.5) {
                    complianceDelta -= 14; roiDelta -= this.REMEDIATION; ds.ivassFinding = true; coachKey = `coach_r3_skipgate`;
                }

                summaryKey = (d.launch === `guardrails` && d.oversight === `control`) ? `sum_r3_good` :
                             (d.launch === `modeled` && unguarded ? `sum_r3_blindmodel` :
                             (d.launch === `reject` ? `sum_r3_shelved` : `sum_r3_weak`));
            } else if (round === 4) {
                // Sequence the change under compliance gates; build the agent change plan (Common Error 6 + channel conflict).
                switch (d.sequence) {
                    case `dependency`: progressDelta += 12; qualityDelta += 10; roiDelta += 16; coachKey = `coach_r4_dependency`; break;
                    case `aifirst`: progressDelta -= 6; qualityDelta -= 8; roiDelta -= 14; ds.strandedCapital = true; coachKey = `coach_r4_aifirst`; break;
                    case `channelfirst`: progressDelta += 2; qualityDelta -= 6; roiDelta -= 8; ds.agentRevolt = true; coachKey = `coach_r4_channelfirst`; break;
                }

                // Every high-risk step clears its compliance gate before go-live.
                switch (d.gate) {
                    case `pregate`: complianceDelta += 14; qualityDelta += 6; ds.ivassFinding = false; break;
                    case `parallel`: complianceDelta += 2; break;
                    case `postlaunch`: complianceDelta -= 12; roiDelta -= 10; ds.ivassFinding = true; if (coachKey === `coach_default`) coachKey = `coach_r4_postgate`; break;
                }

                // Change-management plan for the 1,850 agencies carrying 78% of premium.
                switch (d.agentPlan) {
                    case `full`: qualityDelta += 12; progressDelta += 6; roiDelta += 14; ds.agentRevolt = false; break;
                    case `memo`: qualityDelta -= 2; roiDelta -= 4; break;
                    case `none`: qualityDelta -= 10; progressDelta -= 4; roiDelta -= this.LUMO_AT_RISK * 0.25; ds.agentRevolt = true; if (coachKey === `coach_default`) coachKey = `coach_r4_noagent`; break;
                }

                // The board & IVASS pitch — defend the sequence as gated, not front-loaded.
                if (d.pitch >= 60) { qualityDelta += 5; complianceDelta += 4; }
                else if (d.pitch <= 25) { qualityDelta -= 4; complianceDelta -= 2; }

                if (d.sequence === `dependency` && d.gate === `pregate` && d.agentPlan === `full`) coachKey = `coach_r4_boardready`;

                summaryKey = (d.sequence === `dependency` && d.gate === `pregate` && d.agentPlan === `full`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Resource accounting: meter the EUR 90M transformation budget across the rounds.
            if (round === 2) {
                spend = Math.round(d.platformSpend + d.agentSpend + d.aiSpend + d.directSpend);
            }
            ds.budgetUsed = Math.min(this.BUDGET, Math.round(ds.budgetUsed + spend));

            // Apply deltas. Progress/quality start low and climb; compliance starts high and is defended;
            // ROI is signed EUR M.
            ds.progress = Math.max(0, Math.min(100, Math.round(ds.progress + progressDelta)));
            ds.compliance = Math.max(0, Math.min(100, Math.round(ds.compliance + complianceDelta)));
            ds.quality = Math.max(0, Math.min(100, Math.round(ds.quality + qualityDelta)));
            ds.roi = Math.round((ds.roi + roiDelta) * 10) / 10;

            ds.progressHistory.push(ds.progress);
            ds.complianceHistory.push(ds.compliance);
            ds.qualityHistory.push(ds.quality);
            ds.roiHistory.push(ds.roi);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // v1.1.0: persist the composite where results_utils.php reads it (per-period + final):
            //   express_resolveDomainScore -> domainState.performance.overallScore (then top-level score)
            //   express_extractHistory     -> domainState.performance.overallScore / results.score
            const _score = this._composite(ds);
            ds.score = _score;
            if (!ds.performance || typeof ds.performance !== `object`) { ds.performance = {}; }
            ds.performance.overallScore = _score;

            return {
                period: state.currentPeriod,
                score: _score,
                progress: ds.progress,
                progressDelta: Math.round(progressDelta),
                compliance: ds.compliance,
                complianceDelta: Math.round(complianceDelta),
                quality: ds.quality,
                qualityDelta: Math.round(qualityDelta),
                roi: ds.roi,
                roiDelta: Math.round(roiDelta * 10) / 10,
                budgetUsed: ds.budgetUsed,
                ivassFinding: ds.ivassFinding,
                agentRevolt: ds.agentRevolt,
                strandedCapital: ds.strandedCapital,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _fmtMoney(v) {
            // Locale-aware EUR (EUR M): English "€16.0M", Spanish "16,0 M€" (comma decimal, symbol after).
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const sign = v < 0 ? `-` : ``;
            const abs = Math.abs(v);
            if (lang === `es`) {
                return `${sign}${abs.toFixed(1).replace(`.`, `,`)} M€`;
            }
            return `${sign}€${abs.toFixed(1)}M`;
        }

        _fmtBudget(v) {
            // Whole EUR M for the capital bar.
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const n = Math.round(v);
            return (lang === `es`) ? `${n} M€` : `€${n}M`;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`progressDisplay`, `domainState.progress`, (v) => Math.round(Number(v)));
            uiManager.bind(`complianceDisplay`, `domainState.compliance`, (v) => {
                const card = document.querySelector(`.trsim-card-compliance`);
                if (card) {
                    card.classList.toggle(`trsim-compliance-breach`, Number(v) <= 35);
                    card.classList.toggle(`trsim-compliance-strong`, Number(v) >= 80);
                }
                return Math.round(Number(v));
            });
            uiManager.bind(`qualityDisplay`, `domainState.quality`, (v) => Math.round(Number(v)));
            uiManager.bind(`roiDisplay`, `domainState.roi`, (v) => {
                const card = document.querySelector(`.trsim-card-roi`);
                if (card) {
                    card.classList.toggle(`trsim-roi-positive`, Number(v) > 0.05);
                    card.classList.toggle(`trsim-roi-negative`, Number(v) < -0.05);
                }
                return self._fmtMoney(Number(v));
            });
            uiManager.bind(`budgetDisplay`, `domainState.budgetUsed`, (v) => {
                return self._fmtBudget(Number(v)) + ` / ` + self._fmtBudget(self.BUDGET);
            });

            // Thesis slider readout.
            const ts = document.getElementById(`thesisInput`);
            const tsReadout = document.getElementById(`thesisReadout`);
            if (ts && tsReadout) {
                tsReadout.textContent = ts.value;
                ts.addEventListener(`input`, function() { tsReadout.textContent = ts.value; });
            }

            // Segment slider readout.
            const sg = document.getElementById(`segmentInput`);
            const sgReadout = document.getElementById(`segmentReadout`);
            if (sg && sgReadout) {
                sgReadout.textContent = sg.value;
                sg.addEventListener(`input`, function() { sgReadout.textContent = sg.value; });
            }

            // Capital allocation live total (must hit EUR 90M).
            const allocIds = [`platformSpendInput`, `agentSpendInput`, `aiSpendInput`, `directSpendInput`];
            const allocReadout = document.getElementById(`allocReadout`);
            const recompute = function() {
                let total = 0;
                allocIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseFloat(el.value) || 0);
                });
                total = Math.round(total);
                if (allocReadout) allocReadout.textContent = total;
                const bar = document.querySelector(`.trsim-alloc-readout`);
                if (bar) bar.style.color = (Math.abs(total - self.BUDGET) > 0.001) ? `#c0392b` : ``;
            };
            allocIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

