        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.progressHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            return {
                trsimChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.progressHistory },
                        { data: ds.complianceHistory },
                        { data: ds.qualityHistory }
                    ]
                }
            };
