        _composite(ds) {
            // v1.1.0: verbatim v1.0.0 formula, extracted so calculateResults can persist it every period.
            const progress = Math.round(ds.progress);
            const compliance = Math.round(ds.compliance);
            const quality = Math.round(ds.quality);
            const roi = ds.roi;
            const roiScore = Math.max(-25, Math.min(25, roi * 0.5));
            return Math.round(progress * 0.28 + compliance * 0.28 + quality * 0.28 + (roiScore + 25) * 0.32);
        }

        formatCompletionMessage(summary) {
            // v1.1.0: localized debrief. Without this override the engine renders a generic
            // "You completed N periods" and discards the score, tier and insights.
            const t = (k) => (window.mySimulation ? window.mySimulation.t(k) : k);
            if (!summary || typeof summary.composite === `undefined`) {
                return `<div class="tr-cm"><div class="tr-cm-tier">${t(`grade_stalled`)}</div></div>`;
            }
            const tier = summary.performance || t(summary.performanceKey || `grade_stalled`);
            const chip = (ok, label) => `<div class="tr-cm-chip ${ok ? `is-met` : `is-missed`}"><span class="tr-cm-chip-l">${label}</span><span class="tr-cm-badge ${ok ? `is-met` : `is-missed`}">${ok ? t(`cm_met`) : t(`cm_missed`)}</span></div>`;
            const lis = (summary.insights || []).map((s) => `<li>${s}</li>`).join(``);
            return `
                <div class="tr-cm">
                    <div class="tr-cm-head">
                        <div class="tr-cm-scorebox">
                            <div class="tr-cm-score">${summary.composite}<span class="tr-cm-score-max">/100</span></div>
                            <div class="tr-cm-score-label">${t(`cm_score_label`)}</div>
                        </div>
                        <div class="tr-cm-tier">${tier}</div>
                    </div>
                    <div class="tr-cm-chips">
                        ${chip(summary.profitable, t(`cm_chip_profitable`))}
                        ${chip(summary.compliant, t(`cm_chip_compliant`))}
                        ${chip(summary.wellJudged, t(`cm_chip_judged`))}
                    </div>
                    <div class="tr-cm-kpis">
                        <div class="tr-cm-kpi"><div class="tr-cm-kpi-v">${summary.progress}</div><div class="tr-cm-kpi-l">${t(`cm_kpi_progress`)}</div></div>
                        <div class="tr-cm-kpi"><div class="tr-cm-kpi-v">${summary.compliance}</div><div class="tr-cm-kpi-l">${t(`cm_kpi_compliance`)}</div></div>
                        <div class="tr-cm-kpi"><div class="tr-cm-kpi-v">${summary.quality}</div><div class="tr-cm-kpi-l">${t(`cm_kpi_quality`)}</div></div>
                        <div class="tr-cm-kpi"><div class="tr-cm-kpi-v">${this._fmtMoney(Number(summary.roi))}</div><div class="tr-cm-kpi-l">${t(`cm_kpi_roi`)}</div></div>
                    </div>
                    <div class="tr-cm-insights">
                        <div class="tr-cm-insights-title">${t(`cm_insights_title`)}</div>
                        <ul>${lis}</ul>
                    </div>
                </div>
            `;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const progress = Math.round(ds.progress);
            const compliance = Math.round(ds.compliance);
            const quality = Math.round(ds.quality);
            const roi = ds.roi;

            // Composite: progress, compliance, decision quality, plus an ROI bonus
            // (normalised: each EUR M of ROI worth ~0.5 points, capped at ±25).
            // v1.1.0: composite via _composite(ds) — single source of truth, value byte-identical to v1.0.0.
            const composite = this._composite(ds);

            const profitable = roi >= 0;
            const compliant = compliance >= 60 && !ds.ivassFinding;
            const wellJudged = quality >= 60;
            const finding = ds.ivassFinding || compliance <= 35;

            // v1.1.0: tier is now i18n-keyed (was hardcoded English) so it localizes.
            let performanceKey = `grade_stalled`;
            if (profitable && compliant && wellJudged && composite >= 75) performanceKey = `grade_modernized`;
            else if (compliant && wellJudged) performanceKey = `grade_coherent`;
            else if (finding) performanceKey = `grade_finding`;
            else if (ds.agentRevolt) performanceKey = `grade_revolt`;
            else if (ds.strandedCapital) performanceKey = `grade_stranded`;
            else if (composite >= 55) performanceKey = `grade_mixed`;
            const performance = window.mySimulation.t(performanceKey);

            const insights = [];
            if (profitable && compliant && wellJudged) insights.push(window.mySimulation.t(`insight_resilient`));
            else if (finding) insights.push(window.mySimulation.t(`insight_finding`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (roi < 0) insights.push(window.mySimulation.t(`insight_roi_negative`));
            else if (roi >= 30) insights.push(window.mySimulation.t(`insight_roi_strong`));
            if (ds.ivassFinding) insights.push(window.mySimulation.t(`insight_ivass`));
            if (ds.agentRevolt) insights.push(window.mySimulation.t(`insight_agents`));
            if (ds.strandedCapital) insights.push(window.mySimulation.t(`insight_stranded`));
            if (compliance >= 80 && quality >= 65) insights.push(window.mySimulation.t(`insight_designparam`));

            return {
                totalPeriods: history.length,
                progress: progress,
                compliance: compliance,
                quality: quality,
                roi: roi,
                profitable: profitable,
                compliant: compliant,
                wellJudged: wellJudged,
                finding: finding,
                composite: composite,
                performanceKey: performanceKey,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.ivassFinding) return window.mySimulation.t(`hint_ivass`);
            if (ds.agentRevolt) return window.mySimulation.t(`hint_agents`);
            if (ds.strandedCapital && state.currentPeriod >= 2) return window.mySimulation.t(`hint_stranded`);
            if (ds.compliance <= 35) return window.mySimulation.t(`hint_compliance`);
            if (ds.roi <= -20 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_roi`);
            if (ds.progress >= 60 && ds.compliance >= 65 && ds.quality >= 60) return window.mySimulation.t(`hint_strong`);
            return null;
        }

